namespace idx2f_dlc {

constexpr int kHeads = 32;
constexpr int kHeadDim = 128;     // fp8 bytes per index key
constexpr int kPage = 64;         // indexer K-cache page (ratio-1 layers; DeepGEMM sm90 asserts block_kv == 64)
constexpr int kBlock = 8;         // candidate block size (config candidate_block_size)
constexpr int kTileTok = 64;      // = DeepGEMM kComputeBlockKV
constexpr int kBlkPerTile = kTileTok / kBlock;
constexpr int kMathWG = 4;        // = DeepGEMM kNumMathThreads 512 / 128
constexpr int kMathThreads = kMathWG * 128;
constexpr int kTMAThreads = 128;  // one producer warp per math warpgroup (+ Q on warp 0)
constexpr int kThreads = kMathThreads + kTMAThreads;
constexpr int kQStages = 2;
constexpr int kKVStages = 3;
constexpr int kKVTileBytes = kTileTok * kHeadDim;  // 8 KB
constexpr int kSubKVBytes = kBlock * kHeadDim;     // 1 KB = one TMA box (one 128B-swizzle atom)
constexpr int kScTileBytes = kTileTok * 4;
constexpr int kSubScBytes = kBlock * 4;            // 32 B (cp.async.bulk, 16 B granule)
constexpr int kPageValBytes = kPage * kHeadDim;    // scales follow the 64 x 128 values inside a page
constexpr int kMaxCand = 2048;                     // candidate_topk_blocks
constexpr int kNumTMARegisters = 64;               // = DeepGEMM
constexpr int kNumMathRegisters = 104;             // = DeepGEMM

template <int NEXT_N>
struct Cfg {
  static_assert(NEXT_N == 1 || NEXT_N == 2 || NEXT_N == 4, "NEXT_N in {1, 2, 4} (DeepGEMM sm90 paged MQA)");
  // Rows per WGMMA = DeepGEMM kNextNPerCTA: next_n 1 -> 1 (N 32), next_n 2 -> 2 (N 64, multicast 1),
  // next_n 4 -> 2 (N 64, 2-CTA cluster: CTA rank p takes rows 2p, 2p+1). Here one CTA runs both row pairs on one KV tile.
  static constexpr int RPM = NEXT_N >= 2 ? 2 : 1;
  static constexpr int NPAIR = NEXT_N / RPM;
  static constexpr int N = RPM * kHeads;
  static constexpr int QBytes = NEXT_N * kHeads * kHeadDim;
  static constexpr int PairQBytes = RPM * kHeads * kHeadDim;
  static constexpr int WBytes = NEXT_N * kHeads * 4;
  static constexpr int OffQ = 0;                                           // 1024-aligned TMA (128B swizzle)
  static constexpr int OffKV = OffQ + kQStages * QBytes;                   // [WG][stage] 8 KB tiles, 1024-aligned
  static constexpr int OffW = OffKV + kMathWG * kKVStages * kKVTileBytes;  // [stage] weights (cp.async.bulk)
  static constexpr int OffSc = OffW + kQStages * WBytes;                   // [WG][stage] 64 fp32 kv scales
  static constexpr int OffBar = OffSc + kMathWG * kKVStages * kScTileBytes;
  static constexpr int NumBars = 2 * kQStages + 2 * kMathWG * kKVStages;
  static constexpr int OffTask = OffBar + NumBars * 8;                     // int task_off[B + 1], int nunion[B]
  static_assert(QBytes % 1024 == 0 && PairQBytes % 1024 == 0 && OffKV % 1024 == 0, "swizzle alignment");
  static_assert(OffW % 16 == 0 && WBytes % 16 == 0 && OffSc % 16 == 0 && OffBar % 8 == 0, "alignment");
  static int smem_bytes(int B) { return 1024 + OffTask + (2 * B + 1) * 4; }  // + 1 KB for the manual base alignment
};

// ------------------------------------------------------------------------------------------------ prep (union / compaction)
// One CTA per request. Bitmaps over the request's blocks (smem, NEXT_N x nwords_max words) make the union ascending and
// duplicate-free whatever the candidate order (stock select: descending score; ds41h select_blocks: ascending) and drop
// -1 padding and blocks at or past the row's end, exactly the blocks _mask_candidates_kernel keeps for this row.
template <int NEXT_N>
struct Cnt {
  int v[NEXT_N + 1];  // [0] union, [1 + r] row r
};
template <int NEXT_N>
struct CntSum {
  __device__ __forceinline__ Cnt<NEXT_N> operator()(const Cnt<NEXT_N>& a, const Cnt<NEXT_N>& b) const {
    Cnt<NEXT_N> c;
#pragma unroll
    for (int i = 0; i <= NEXT_N; ++i) c.v[i] = a.v[i] + b.v[i];
    return c;
  }
};

constexpr int kPrepThreads = 512;  // 128 registers per thread: no spills with the 5-int scan of NEXT_N 4

struct PrepArgs {
  const int* cand;   // [rows, K] block ids (any order, -1 padded)
  long cand_stride;
  int K;
  const int* ctx;    // [rows] row ends (= context_lens [B, NEXT_N] flattened)
  int nwords_max;    // bitmap words per row (ceil(ceil(max_model_len / 8) / 32))
  int* ublk;         // [B, ustride] union block ids, ascending
  int* uslot;        // [B, ustride, NEXT_N] rank of the block in row r's list, -1 if not a candidate of row r
  int ustride;       // NEXT_N * K
  int* nunion;       // [B]
  int* cblk;         // [rows, cblk_stride] row's candidate blocks, ascending (first n_r entries valid)
  long cblk_stride;
  int* clen;         // [rows] compact length = #finite positions of the stock-masked row in [0, row_end)
};

template <int NEXT_N>
__global__ void __launch_bounds__(kPrepThreads) cand_prep_kernel(const PrepArgs a) {
  using Scan = cub::BlockScan<Cnt<NEXT_N>, kPrepThreads>;
  __shared__ typename Scan::TempStorage scan_tmp;
  __shared__ Cnt<NEXT_N> total;
  extern __shared__ unsigned bm[];  // [NEXT_N][nwords_max]
  const int b = blockIdx.x, tid = threadIdx.x;
  const int maxblk = a.nwords_max * 32;
  int L[NEXT_N], nb[NEXT_N], nbmax = 0;
#pragma unroll
  for (int r = 0; r < NEXT_N; ++r) {
    L[r] = max(0, __ldg(a.ctx + b * NEXT_N + r));
    nb[r] = min((L[r] + kBlock - 1) / kBlock, maxblk);  // blocks with 8 * blk < row_end (the mask's `valid` columns)
    nbmax = max(nbmax, nb[r]);
  }
  const int nw = (nbmax + 31) / 32;
  for (int i = tid; i < NEXT_N * nw; i += kPrepThreads) bm[(i / nw) * a.nwords_max + (i % nw)] = 0u;
  __syncthreads();
  for (int i = tid; i < NEXT_N * a.K; i += kPrepThreads) {  // NEXT_N * K is a multiple of 32: whole warps iterate
    const int r = i / a.K, j = i - r * a.K;
    const int blk = __ldg(a.cand + long(b * NEXT_N + r) * a.cand_stride + j);
    // stock _candidate_flags_kernel / _mask_candidates_kernel: -1 is ignored; a block keeps columns 8*blk.. only inside
    // [0, row_end); the "edge" clamp (start + 8*blk >= width) needs 8*blk >= width >= row_end: never inside the row.
    int nbr = nb[0];
#pragma unroll
    for (int q = 1; q < NEXT_N; ++q) nbr = r == q ? nb[q] : nbr;
    const bool ok = blk >= 0 && blk < nbr;
    // idx2f: one atomicOr per distinct word per warp. The candidate lists are ascending, so a warp's 32
    // blocks share one or two words and plain atomics serialized 32-way (prep took 45-54 us at 24 requests).
    const unsigned word = ok ? unsigned(r * a.nwords_max + (blk >> 5)) : 0xffffffffu;
    const unsigned peers = __match_any_sync(0xffffffffu, word);
    const unsigned bits = __reduce_or_sync(peers, ok ? 1u << (blk & 31) : 0u);
    if (ok && int(threadIdx.x & 31) == __ffs(peers) - 1) atomicOr(&bm[word], bits);
  }
  __syncthreads();
  const int chunk = (nw + kPrepThreads - 1) / kPrepThreads;
  const int w0 = min(nw, tid * chunk), w1 = min(nw, w0 + chunk);
  Cnt<NEXT_N> c;
#pragma unroll
  for (int i = 0; i <= NEXT_N; ++i) c.v[i] = 0;
  for (int w = w0; w < w1; ++w) {
    unsigned u = 0;
#pragma unroll
    for (int r = 0; r < NEXT_N; ++r) {
      const unsigned m = bm[r * a.nwords_max + w];
      u |= m;
      c.v[1 + r] += __popc(m);
    }
    c.v[0] += __popc(u);
  }
  Cnt<NEXT_N> base, agg;
  Scan(scan_tmp).ExclusiveScan(c, base, Cnt<NEXT_N>{}, CntSum<NEXT_N>(), agg);
  if (tid == 0) total = agg;
  int* ublk = a.ublk + long(b) * a.ustride;
  int* uslot = a.uslot + long(b) * a.ustride * NEXT_N;
  for (int w = w0; w < w1; ++w) {
    unsigned m[NEXT_N], u = 0;
#pragma unroll
    for (int r = 0; r < NEXT_N; ++r) u |= (m[r] = bm[r * a.nwords_max + w]);
    while (u) {
      const int bit = __ffs(u) - 1;
      u &= u - 1;
      const int blk = w * 32 + bit, ui = base.v[0]++;
      ublk[ui] = blk;
#pragma unroll
      for (int r = 0; r < NEXT_N; ++r) {
        int s = -1;
        if ((m[r] >> bit) & 1u) {
          s = base.v[1 + r]++;
          a.cblk[long(b * NEXT_N + r) * a.cblk_stride + s] = blk;
        }
        uslot[long(ui) * NEXT_N + r] = s;
      }
    }
  }
  __syncthreads();
  if (tid == 0) {
    a.nunion[b] = total.v[0];
#pragma unroll
    for (int r = 0; r < NEXT_N; ++r) {
      const int n = total.v[1 + r];
      // Only the row's newest block (row_end - 1) / 8 can be partial; every other kept block lies inside [0, row_end).
      const int newest = nb[r] - 1;
      const bool has = n > 0 && ((bm[r * a.nwords_max + (newest >> 5)] >> (newest & 31)) & 1u);
      const int tail = L[r] - kBlock * newest;  // 1..8
      a.clen[b * NEXT_N + r] = n * kBlock - (has ? kBlock - tail : 0);
    }
  }
}

// ------------------------------------------------------------------------------------------------ candidate logits
struct LogitsArgs {
  const int* nunion;       // [B]
  const int* ublk;         // [B, ustride]
  const int* uslot;        // [B, ustride, NEXT_N]
  int ustride;
  const int* ctx;          // [B * NEXT_N] row ends
  const int* block_table;  // [B, bt_stride]
  long bt_stride;
  const float* weights;    // [B * NEXT_N, 32] contiguous
  const uint8_t* kv;       // fused paged index-K cache: page p at kv + p * page_stride: 64 x 128 fp8, then 64 fp32 scales
  long page_stride;
  int num_pages;           // kv.size(0): block-table entries outside [0, num_pages) read zeros (= stock's tensor maps)
  float* out;              // [B * NEXT_N, out_stride] compact logits
  long out_stride;
  int B;
  const int* upk;          // idx2f: optional [B, ustride] packed (page << 3) | (blk & 7) of each union block (prep2), else
                           // the producer reads ublk then the block table (two dependent loads per tile)
  int dense;               // idx2f dense mode (layers 2 / 8 / 14 / 20 instead of DeepGEMM): the union of a request is
                           // all of its blocks [0, ceil(max_r L_r / 8)), position = 8 * block + offset; ublk / uslot /
                           // nunion unused; whole pages per TMA box (tm_kvp)
  int page_tok;            // tokens (compressed positions) per index-K page: 64 (ratio 1) or 32 (ratio 2)
};

using Barrier = cutlass::arch::ClusterTransactionBarrier;

// Task = (request b, chunk t): math warpgroup g scores union tile 4 t + g (64 tokens = 8 candidate blocks), the way the
// dense kernel's 4 math warpgroups score the 4 x 64-token blocks of one 256-token split. Every CTA walks a contiguous,
// equally sized range of the global task list (tasks have equal cost), in request order.
struct TaskIter {
  const int* off;
  int g, hi, b;
  __device__ __forceinline__ bool next(int& tb, int& tt) {
    if (g >= hi) return false;
    while (off[b + 1] <= g) ++b;
    tb = b, tt = g - off[b], ++g;
    return true;
  }
};

template <int NEXT_N>
__global__ void __launch_bounds__(kThreads, 1)
    cand_logits_kernel(const __grid_constant__ LogitsArgs a, const __grid_constant__ CUtensorMap tm_q,
                       const __grid_constant__ CUtensorMap tm_kv, const __grid_constant__ CUtensorMap tm_kvp) {
  using C = Cfg<NEXT_N>;
  using WGMMA = typename deep_gemm::mma::sm90::FP8MMASelector<C::N>::type;
  namespace ptx = deep_gemm::ptx;
  extern __shared__ uint8_t smem_raw[];
  uint8_t* smem = reinterpret_cast<uint8_t*>((reinterpret_cast<uintptr_t>(smem_raw) + 1023) & ~uintptr_t(1023));
  const int warp_idx = __shfl_sync(0xffffffffu, int(threadIdx.x) / 32, 0);
  const int lane = int(ptx::get_lane_idx());
  int* task_off = reinterpret_cast<int*>(smem + C::OffTask);
  int* s_nu = task_off + a.B + 1;
  Barrier* bars = reinterpret_cast<Barrier*>(smem + C::OffBar);
  Barrier* full_q = bars;
  Barrier* empty_q = bars + kQStages;
  Barrier* full_kv = bars + 2 * kQStages;                         // [WG][stage]
  Barrier* empty_kv = bars + 2 * kQStages + kMathWG * kKVStages;  // [WG][stage]

  // Task prefix over requests (warp 0): ntask_b = ceil(nunion_b / 32) chunks of 4 tiles.
  if (warp_idx == 0) {
    const int per = (a.B + 31) / 32, j0 = min(a.B, lane * per), j1 = min(a.B, j0 + per);
    int s = 0;
    for (int j = j0; j < j1; ++j) {
      int nu;
      if (a.dense) {
        int mx = 0;
#pragma unroll
        for (int r = 0; r < NEXT_N; ++r) mx = max(mx, __ldg(a.ctx + j * NEXT_N + r));
        nu = (mx + kBlock - 1) / kBlock;
      } else {
        nu = __ldg(a.nunion + j);
      }
      s_nu[j] = nu;
      s += (nu + kBlkPerTile * kMathWG - 1) / (kBlkPerTile * kMathWG);
    }
    int inc = s;
#pragma unroll
    for (int o = 1; o < 32; o <<= 1) {
      const int y = __shfl_up_sync(0xffffffffu, inc, o);
      if (lane >= o) inc += y;
    }
    int run = inc - s;
    for (int j = j0; j < j1; ++j) {
      task_off[j] = run;
      run += (s_nu[j] + kBlkPerTile * kMathWG - 1) / (kBlkPerTile * kMathWG);
    }
    if (lane == 31) task_off[a.B] = inc;
  }
  if (warp_idx == kMathThreads / 32 && cute::elect_one_sync()) {
    for (int i = 0; i < kQStages; ++i) full_q[i].init(1), empty_q[i].init(kMathThreads);
    for (int i = 0; i < kMathWG * kKVStages; ++i) full_kv[i].init(1), empty_kv[i].init(128);
    cutlass::arch::fence_barrier_init();
  }
  __syncthreads();
  const long total = task_off[a.B];
  const int lo = int(total * blockIdx.x / gridDim.x), hi = int(total * (blockIdx.x + 1) / gridDim.x);
  if (lo >= hi) return;
  TaskIter it{task_off, lo, hi, 0};

  if (warp_idx >= kMathThreads / 32) {
    // ------------------------------------------------------------------ producers
    cutlass::arch::warpgroup_reg_dealloc<kNumTMARegisters>();
    const int g = warp_idx - kMathThreads / 32;
    uint32_t kv_iter = 0, q_iter = 0;
    int cur_b = -1, b, t;
    while (it.next(b, t)) {
      if (g == 0 && b != cur_b) {
        const uint32_t qs = q_iter % kQStages, qph = (q_iter / kQStages) & 1;
        ++q_iter;
        empty_q[qs].wait(qph ^ 1);
        if (cute::elect_one_sync()) {
          uint8_t* sq = smem + C::OffQ + qs * C::QBytes;
          cute::SM90_TMA_LOAD_2D::copy(&tm_q, reinterpret_cast<uint64_t*>(&full_q[qs]),
                                       static_cast<uint64_t>(cute::TMA::CacheHintSm90::EVICT_NORMAL), sq, 0,
                                       b * NEXT_N * kHeads);
          cute::SM90_BULK_COPY_G2S::copy(a.weights + long(b) * NEXT_N * kHeads, reinterpret_cast<uint64_t*>(&full_q[qs]),
                                         smem + C::OffW + qs * C::WBytes, C::WBytes);
          full_q[qs].arrive_and_expect_tx(C::QBytes + C::WBytes);
        }
        __syncwarp();
      }
      cur_b = b;
      const int nu = s_nu[b];
      const int tile = t * kMathWG + g;
      if (tile * kBlkPerTile >= nu) continue;
      if (a.dense) {
        // whole pages: 64 / page_tok boxes of [128 B x page_tok] + their scales; a page past the request's last block
        // (second half of a ratio-2 tile) loads the tile's first page again (values masked by the row ends, as stock's
        // block-0 reads)
        const int P = a.page_tok, npp = kTileTok / P, tok0 = tile * kTileTok;
        int pg = 0;
        if (lane < npp) {
          const int pi = (tok0 + lane * P < nu * kBlock) ? tok0 / P + lane : tok0 / P;
          pg = __ldg(a.block_table + long(b) * a.bt_stride + pi);
        }
        const uint32_t ks = kv_iter % kKVStages, kph = (kv_iter / kKVStages) & 1;
        ++kv_iter;
        Barrier& fb = full_kv[g * kKVStages + ks];
        empty_kv[g * kKVStages + ks].wait(kph ^ 1);
        if (lane < npp) {
          uint8_t* skv = smem + C::OffKV + (g * kKVStages + ks) * kKVTileBytes + lane * P * kHeadDim;
          cute::SM90_TMA_LOAD_3D::copy(&tm_kvp, reinterpret_cast<uint64_t*>(&fb),
                                       static_cast<uint64_t>(cute::TMA::CacheHintSm90::EVICT_NORMAL), skv, 0, 0, pg);
          uint8_t* ssc = smem + C::OffSc + (g * kKVStages + ks) * kScTileBytes + lane * P * 4;
          cute::SM90_BULK_COPY_G2S::copy(a.kv + long(pg) * a.page_stride + P * kHeadDim, reinterpret_cast<uint64_t*>(&fb),
                                         ssc, P * 4);
        }
        __syncwarp();
        if (lane == 0) fb.arrive_and_expect_tx(kTileTok * (kHeadDim + 4));
        __syncwarp();
        continue;
      }
      const int nvalid = min(kBlkPerTile, nu - tile * kBlkPerTile);
      // idx2f: the tile's page indices are loaded BEFORE the slot wait (their latency overlaps it)
      int page = 0, tip = 0;
      if (lane < nvalid) {
        if (a.upk != nullptr) {
          const int v = __ldg(a.upk + long(b) * a.ustride + tile * kBlkPerTile + lane);
          page = v >> 3, tip = (v & 7) * kBlock;
        } else {
          const int blk = __ldg(a.ublk + long(b) * a.ustride + tile * kBlkPerTile + lane);
          const int tok = blk * kBlock;
          page = __ldg(a.block_table + long(b) * a.bt_stride + tok / kPage);
          tip = tok % kPage;
        }
      }
      const uint32_t ks = kv_iter % kKVStages, kph = (kv_iter / kKVStages) & 1;
      ++kv_iter;
      Barrier& fb = full_kv[g * kKVStages + ks];
      empty_kv[g * kKVStages + ks].wait(kph ^ 1);
      bool scale_copy = false;
      if (lane < nvalid) {
        uint8_t* skv = smem + C::OffKV + (g * kKVStages + ks) * kKVTileBytes + lane * kSubKVBytes;
        // Values: the tensor map zero-fills a page outside [0, num_pages) and still counts the full box (as stock).
        cute::SM90_TMA_LOAD_3D::copy(&tm_kv, reinterpret_cast<uint64_t*>(&fb),
                                     static_cast<uint64_t>(cute::TMA::CacheHintSm90::EVICT_NORMAL), skv, 0, tip, page);
        uint8_t* ssc = smem + C::OffSc + (g * kKVStages + ks) * kScTileBytes + lane * kSubScBytes;
        scale_copy = page >= 0 && page < a.num_pages;
        if (scale_copy) {
          cute::SM90_BULK_COPY_G2S::copy(a.kv + long(page) * a.page_stride + kPageValBytes + tip * 4,
                                         reinterpret_cast<uint64_t*>(&fb), ssc, kSubScBytes);
        } else {
          // Stock reads the scales through a tensor map too: an out-of-range page gives zeros. Plain shared stores,
          // read by the math warps' plain shared loads after the barrier (the arrive below releases them).
          reinterpret_cast<float4*>(ssc)[0] = make_float4(0.f, 0.f, 0.f, 0.f);
          reinterpret_cast<float4*>(ssc)[1] = make_float4(0.f, 0.f, 0.f, 0.f);
        }
      }
      const int ncopies = __popc(__ballot_sync(0xffffffffu, scale_copy));
      __syncwarp();
      if (lane == 0) fb.arrive_and_expect_tx(nvalid * kSubKVBytes + ncopies * kSubScBytes);
      __syncwarp();
    }
  } else {
    // ------------------------------------------------------------------ math warpgroups (DeepGEMM math path)
    cutlass::arch::warpgroup_reg_alloc<kNumMathRegisters>();
    const int wg = warp_idx / 4;
    float accum[WGMMA::kNumAccum];
    const uint32_t sub_warp_offset = (warp_idx % 4) * 16;
    const uint32_t v_0_offset = lane / 4 + 0;
    const uint32_t v_1_offset = lane / 4 + 8;
    uint32_t kv_iter = 0, q_iter = 0, qs = 0;
    int cur_b = -1, nu = 0, b, t;
    int L[NEXT_N];
    while (it.next(b, t)) {
      if (b != cur_b) {
        if (cur_b >= 0) empty_q[qs].arrive();
        qs = q_iter % kQStages;
        const uint32_t qph = (q_iter / kQStages) & 1;
        ++q_iter;
        full_q[qs].wait(qph);
        cur_b = b;
        nu = s_nu[b];
#pragma unroll
        for (int r = 0; r < NEXT_N; ++r) L[r] = __ldg(a.ctx + b * NEXT_N + r);
      }
      const int tile = t * kMathWG + wg;
      if (tile * kBlkPerTile >= nu) continue;
      // This warp's 16 tile rows are tokens 16 w .. 16 w + 15 = union entries u0 (rows v_0) and u0 + 1 (rows v_1).
      const int u0 = tile * kBlkPerTile + (warp_idx % 4) * 2, u1 = u0 + 1;
      const bool ok0 = u0 < nu, ok1 = u1 < nu;
      int pos0 = -1, pos1 = -1, slot0[NEXT_N], slot1[NEXT_N];
#pragma unroll
      for (int r = 0; r < NEXT_N; ++r) slot0[r] = slot1[r] = -1;
      if (lane % 4 == 0 && a.dense) {
        pos0 = u0 * kBlock + int(v_0_offset);
        pos1 = u1 * kBlock + int(v_0_offset);
#pragma unroll
        for (int r = 0; r < NEXT_N; ++r) {
          slot0[r] = (ok0 && u0 * kBlock < L[r]) ? u0 : -1;
          slot1[r] = (ok1 && u1 * kBlock < L[r]) ? u1 : -1;
        }
      } else if (lane % 4 == 0) {
        if (ok0) pos0 = __ldg(a.ublk + long(b) * a.ustride + u0) * kBlock + int(v_0_offset);
        if (ok1) pos1 = __ldg(a.ublk + long(b) * a.ustride + u1) * kBlock + int(v_0_offset);
#pragma unroll
        for (int r = 0; r < NEXT_N; ++r) {
          if (ok0) slot0[r] = __ldg(a.uslot + (long(b) * a.ustride + u0) * NEXT_N + r);
          if (ok1) slot1[r] = __ldg(a.uslot + (long(b) * a.ustride + u1) * NEXT_N + r);
        }
      }
      const uint32_t ks = kv_iter % kKVStages, kph = (kv_iter / kKVStages) & 1;
      ++kv_iter;
      full_kv[wg * kKVStages + ks].wait(kph);
      uint8_t* skv = smem + C::OffKV + (wg * kKVStages + ks) * kKVTileBytes;
      const float* ssc = reinterpret_cast<const float*>(smem + C::OffSc + (wg * kKVStages + ks) * kScTileBytes);
      const float* sw = reinterpret_cast<const float*>(smem + C::OffW + qs * C::WBytes);
      float scale_kv_0 = 0.f, scale_kv_1 = 0.f;
#pragma unroll
      for (int p = 0; p < C::NPAIR; ++p) {
        uint8_t* sq = smem + C::OffQ + qs * C::QBytes + p * C::PairQBytes;
        // Issue WGMMA (= DeepGEMM sm90_fp8_paged_mqa_logits.cuh: A = KV tile, B = Q of the row pair, K = 128 in 4 steps)
#pragma unroll
        for (uint32_t i = 0; i < WGMMA::kNumAccum; ++i) ptx::warpgroup_fence_operand(accum[i]);
        ptx::warpgroup_arrive();
#pragma unroll
        for (uint32_t k = 0; k < kHeadDim / WGMMA::K; ++k) {
          auto desc_a = deep_gemm::mma::sm90::make_smem_desc(
              reinterpret_cast<__nv_fp8_e4m3*>(skv) + k * WGMMA::K, deep_gemm::mma::sm90::to_swizzle_cute_type<kHeadDim>(),
              0, kHeadDim * 8);
          auto desc_b = deep_gemm::mma::sm90::make_smem_desc(
              reinterpret_cast<__nv_fp8_e4m3*>(sq) + k * WGMMA::K, deep_gemm::mma::sm90::to_swizzle_cute_type<kHeadDim>(),
              0, kHeadDim * 8);
          WGMMA::wgmma(desc_a, desc_b, accum, k);
        }
        ptx::warpgroup_commit_batch();
#pragma unroll
        for (uint32_t i = 0; i < WGMMA::kNumAccum; ++i) ptx::warpgroup_fence_operand(accum[i]);
        if (p == 0) {
          // Read per-KV scales
          scale_kv_0 = ptx::ld_shared(ssc + sub_warp_offset + v_0_offset);
          scale_kv_1 = ptx::ld_shared(ssc + sub_warp_offset + v_1_offset);
        }
        ptx::warpgroup_wait<0>();
        if (p == C::NPAIR - 1) empty_kv[wg * kKVStages + ks].arrive();

        // Reduce over the head dim and store (verbatim DeepGEMM epilogue; weights read from smem per row)
        static constexpr uint32_t kNumAccumPerReduce = kHeads / 2;
        static_assert(WGMMA::kNumAccum % kNumAccumPerReduce == 0, "Invalid accumulation");
        static_assert(WGMMA::kNumAccum / kNumAccumPerReduce == C::RPM, "Invalid accumulation");
#pragma unroll
        for (uint32_t i = 0; i < C::RPM; ++i) {
          const int r = p * C::RPM + int(i);
          float weights[kHeads / 4];
#pragma unroll
          for (uint32_t j = 0; j < kHeads / 4; ++j)
            weights[j] = ptx::ld_shared(sw + r * kHeads + (j / 2) * 8 + (j & 1) + (lane % 4) * 2);
          auto shifted_accum = accum + i * kNumAccumPerReduce;
          const auto transform = [&](const uint32_t& j) { return fmaxf(shifted_accum[j], 0) * weights[(j / 4) * 2 + (j & 1)]; };

          // Intra-thread reduction
          float sum[4] = {transform(0), transform(1), transform(2), transform(3)};
#pragma unroll
          for (uint32_t j = 1; j < kHeads / 8; ++j) {
#pragma unroll
            for (uint32_t k = 0; k < 4; k++) sum[k] += transform(j * 4 + k);
          }
          float v_0 = (sum[0] + sum[1]) * scale_kv_0;
          float v_1 = (sum[2] + sum[3]) * scale_kv_1;

          // Inter-thread reduction
#pragma unroll
          for (uint32_t j = 0; j < 2; ++j) {
            const auto offset = static_cast<int>(1u << j);
            v_0 += __shfl_xor_sync(0xffffffffu, v_0, offset);
            v_1 += __shfl_xor_sync(0xffffffffu, v_1, offset);
          }

          // Store into the compact row (one lane per quad; the dense kernel's 4 redundant writes carry the same value).
          if (lane % 4 == 0) {
            float* orow = a.out + long(b * NEXT_N + r) * a.out_stride;
            if (slot0[r] >= 0 && pos0 < L[r]) orow[slot0[r] * kBlock + int(v_0_offset)] = v_0;
            if (slot1[r] >= 0 && pos1 < L[r]) orow[slot1[r] * kBlock + int(v_0_offset)] = v_1;
          }
        }
      }
    }
  }
}

// ------------------------------------------------------------------------------------------------ remap
// In place: compact index t (< clen of the row) -> request-local position 8 * cblk[row, t >> 3] + (t & 7); -1 stays -1.
__global__ void cand_remap_kernel(int* idx, long idx_stride, int k, const int* __restrict__ cblk, long cblk_stride) {
  const long row = blockIdx.x;
  int* p = idx + row * idx_stride;
  const int* c = cblk + row * cblk_stride;
  for (int j = threadIdx.x; j < k; j += blockDim.x) {
    const int t = p[j];
    if (t >= 0) p[j] = (__ldg(c + (t >> 3)) << 3) | (t & 7);
  }
}

// ------------------------------------------------------------------------------------------------ host
PFN_cuTensorMapEncodeTiled_v12000 encode_fn() {
  static PFN_cuTensorMapEncodeTiled_v12000 fn = [] {
    void* ptr = nullptr;
    cudaDriverEntryPointQueryResult q{};
    TORCH_CHECK(cudaGetDriverEntryPointByVersion("cuTensorMapEncodeTiled", &ptr, 12000, cudaEnableDefault, &q) == cudaSuccess && ptr,
                "cuTensorMapEncodeTiled not available");
    return reinterpret_cast<PFN_cuTensorMapEncodeTiled_v12000>(ptr);
  }();
  return fn;
}

CUtensorMap encode(const void* base, int rank, const cuuint64_t* dims, const cuuint64_t* strides, const cuuint32_t* box,
                   CUtensorMapSwizzle sw, const char* name) {
  CUtensorMap m;
  cuuint32_t es[5] = {1, 1, 1, 1, 1};
  const CUresult r = encode_fn()(&m, CU_TENSOR_MAP_DATA_TYPE_UINT8, rank, const_cast<void*>(base), dims, strides, box, es, CU_TENSOR_MAP_INTERLEAVE_NONE, sw,
                                 CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
  TORCH_CHECK(r == CUDA_SUCCESS, "cuTensorMapEncodeTiled(", name, ") failed: ", int(r));
  return m;
}

void check_i32(const at::Tensor& t, const char* name) {
  TORCH_CHECK(t.is_cuda() && t.scalar_type() == at::kInt, name, ": int32 CUDA tensor expected");
}

// One static per instantiation: raise the dynamic smem limit once per kernel (prep needs > 48 KB past MAXLEN 786K at
// next_n 4; the logits kernel always needs ~140 KB).
template <int NEXT_N>
void launch_prep(const PrepArgs& a, int B, int smem) {
  static bool set_dev[64] = {};
  int dev = 0;
  cudaGetDevice(&dev);
  bool& set = set_dev[dev];
  if (!set) {
    TORCH_CHECK(cudaFuncSetAttribute(cand_prep_kernel<NEXT_N>, cudaFuncAttributeMaxDynamicSharedMemorySize, 4 * 8192 * 4) == cudaSuccess,
                "prep smem attribute");
    set = true;
  }
  cand_prep_kernel<NEXT_N><<<B, kPrepThreads, smem, at::cuda::getCurrentCUDAStream()>>>(a);
}

constexpr int kMaxB = 1024;  // requests per call (task prefix in smem)

template <int NEXT_N>
void launch_logits(const LogitsArgs& a, const CUtensorMap& tm_q, const CUtensorMap& tm_kv, const CUtensorMap& tm_kvp) {
  static bool set_dev[64] = {};  // once per device, at the largest size (a later capture never changes it)
  int dev = 0;
  cudaGetDevice(&dev);
  bool& set = set_dev[dev];
  if (!set) {
    const int mx = Cfg<NEXT_N>::smem_bytes(kMaxB);
    TORCH_CHECK(cudaFuncSetAttribute(cand_logits_kernel<NEXT_N>, cudaFuncAttributeMaxDynamicSharedMemorySize, mx) == cudaSuccess,
                "logits smem attribute (", mx, " B)");
    set = true;
  }
  const int smem = Cfg<NEXT_N>::smem_bytes(a.B);
  const int sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
  cand_logits_kernel<NEXT_N><<<sms, kThreads, smem, at::cuda::getCurrentCUDAStream()>>>(a, tm_q, tm_kv, tm_kvp);
}

// cand [rows, K] int32 (stride(1) == 1), ctx [rows] int32 contiguous (= context_lens [B, next_n]); outputs preallocated:
// ublk [B, next_n*K], uslot [B, next_n*K, next_n], nunion [B], cblk [rows, >= K], clen [rows] (all int32, contiguous rows).
void prep(at::Tensor cand, at::Tensor ctx, int64_t next_n, int64_t nwords_max, at::Tensor ublk, at::Tensor uslot,
          at::Tensor nunion, at::Tensor cblk, at::Tensor clen) {
  for (auto* p : {&cand, &ctx, &ublk, &uslot, &nunion, &cblk, &clen}) check_i32(*p, "prep");
  TORCH_CHECK(cand.dim() == 2 && cand.stride(1) == 1 && ctx.is_contiguous() && nunion.is_contiguous() && clen.is_contiguous(),
              "prep: layout");
  TORCH_CHECK(ublk.is_contiguous() && uslot.is_contiguous() && cblk.dim() == 2 && cblk.stride(1) == 1, "prep: outputs");
  const int rows = int(cand.size(0)), K = int(cand.size(1));
  TORCH_CHECK(next_n == 1 || next_n == 2 || next_n == 4, "prep: next_n in {1, 2, 4}");
  TORCH_CHECK(rows % next_n == 0 && ctx.numel() >= rows && K > 0 && K <= kMaxCand && cblk.size(0) >= rows && cblk.size(1) >= K,
              "prep: shapes");
  TORCH_CHECK((next_n * K) % 32 == 0, "prep: next_n * K must be a multiple of 32 (warp-uniform loop)");
  const int B = rows / int(next_n);
  TORCH_CHECK(ublk.numel() >= long(B) * next_n * K && uslot.numel() >= long(B) * next_n * K * next_n && nunion.numel() >= B &&
                  clen.numel() >= rows, "prep: output sizes");
  TORCH_CHECK(nwords_max > 0 && nwords_max <= 8192, "prep: nwords_max");
  if (!B) return;
  const c10::cuda::CUDAGuard guard(cand.device());
  PrepArgs a{cand.data_ptr<int>(), cand.stride(0), K, ctx.data_ptr<int>(), int(nwords_max), ublk.data_ptr<int>(),
             uslot.data_ptr<int>(), int(next_n * K), nunion.data_ptr<int>(), cblk.data_ptr<int>(), cblk.stride(0),
             clen.data_ptr<int>()};
  const int smem = int(next_n * nwords_max * 4);
  if (next_n == 4) launch_prep<4>(a, B, smem);
  else if (next_n == 2) launch_prep<2>(a, B, smem);
  else launch_prep<1>(a, B, smem);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

// q [B, next_n, 32, 128] float8_e4m3fn contiguous; kv uint8 [num_pages, 64, 1, 132] (DeepGEMM fused layout, stride(0) =
// page bytes); weights [>= B*next_n, 32] fp32 rows contiguous; ctx [B*next_n] int32; block_table [B, P] int32 stride(1) 1;
// ublk / uslot / nunion from prep; out [B*next_n, cw] fp32 (stride(1) 1). Writes out[row, s] for s < clen[row] only.
void logits(at::Tensor q, at::Tensor kv, at::Tensor weights, at::Tensor ctx, at::Tensor block_table, at::Tensor ublk,
            at::Tensor uslot, at::Tensor nunion, at::Tensor out, std::optional<at::Tensor> upk) {
  TORCH_CHECK(q.is_cuda() && q.scalar_type() == at::kFloat8_e4m3fn && q.dim() == 4 && q.is_contiguous(), "q: [B, next_n, 32, 128] fp8");
  const int B = int(q.size(0)), next_n = int(q.size(1));
  TORCH_CHECK(q.size(2) == kHeads && q.size(3) == kHeadDim, "q: 32 heads x 128");
  TORCH_CHECK(next_n == 1 || next_n == 2 || next_n == 4, "next_n in {1, 2, 4}");
  if (!B) return;
  TORCH_CHECK(kv.is_cuda() && kv.scalar_type() == at::kByte && kv.dim() == 4 && kv.size(1) == kPage && kv.size(2) == 1 &&
                  kv.size(3) == kHeadDim + 4 && kv.stride(0) % 16 == 0 && kv.stride(0) >= kPage * (kHeadDim + 4) &&
                  reinterpret_cast<uintptr_t>(kv.data_ptr()) % 16 == 0, "kv: fused fp8 index-K pages [n, 64, 1, 132]");
  TORCH_CHECK(weights.is_cuda() && weights.scalar_type() == at::kFloat && weights.dim() == 2 && weights.size(1) == kHeads &&
                  weights.stride(1) == 1 && weights.stride(0) == kHeads && weights.size(0) >= long(B) * next_n &&
                  reinterpret_cast<uintptr_t>(weights.data_ptr()) % 16 == 0, "weights: [rows, 32] fp32 contiguous rows");
  for (auto* p : {&ctx, &block_table, &ublk, &uslot, &nunion}) check_i32(*p, "logits");
  TORCH_CHECK(ctx.is_contiguous() && ctx.numel() >= long(B) * next_n && block_table.dim() == 2 && block_table.stride(1) == 1 &&
                  block_table.size(0) >= B && nunion.numel() >= B && ublk.is_contiguous() && uslot.is_contiguous(), "logits: metadata");
  TORCH_CHECK(out.is_cuda() && out.scalar_type() == at::kFloat && out.dim() == 2 && out.stride(1) == 1 && out.size(0) >= long(B) * next_n,
              "out: [rows, cw] fp32");
  TORCH_CHECK(ublk.numel() % B == 0 && uslot.numel() == ublk.numel() * next_n, "ublk / uslot shapes");
  TORCH_CHECK(B <= kMaxB, "logits: at most ", kMaxB, " requests per call");
  const c10::cuda::CUDAGuard guard(q.device());
  const long ustride = ublk.numel() / B;
  TORCH_CHECK(out.size(1) >= ustride / next_n * kBlock, "out width < 8 * K");
  // Q: 2D [B*next_n*32 rows, 128 B], box [128 B, next_n*32 rows], 128B swizzle (= DeepGEMM tensor_map_q, both row pairs).
  const cuuint64_t qd[2] = {cuuint64_t(kHeadDim), cuuint64_t(B) * next_n * kHeads};
  const cuuint64_t qs[1] = {cuuint64_t(kHeadDim)};
  const cuuint32_t qb[2] = {cuuint32_t(kHeadDim), cuuint32_t(next_n * kHeads)};
  const CUtensorMap tm_q = encode(q.data_ptr(), 2, qd, qs, qb, CU_TENSOR_MAP_SWIZZLE_128B, "q");
  // KV values: 3D [128 B, 64 tokens, pages] (strides 128 B, page bytes), box [128, 8, 1] = one candidate block = one
  // 1 KB swizzle atom; 8 boxes at 1 KB offsets rebuild the dense kernel's [64 x 128] 128B-swizzled tile.
  const cuuint64_t kd[3] = {cuuint64_t(kHeadDim), cuuint64_t(kPage), cuuint64_t(kv.size(0))};
  const cuuint64_t kst[2] = {cuuint64_t(kHeadDim), cuuint64_t(kv.stride(0))};
  const cuuint32_t kb[3] = {cuuint32_t(kHeadDim), cuuint32_t(kBlock), 1};
  const CUtensorMap tm_kv = encode(kv.data_ptr(), 3, kd, kst, kb, CU_TENSOR_MAP_SWIZZLE_128B, "kv");
  LogitsArgs a{nunion.data_ptr<int>(), ublk.data_ptr<int>(), uslot.data_ptr<int>(), int(ustride), ctx.data_ptr<int>(),
               block_table.data_ptr<int>(), block_table.stride(0), weights.data_ptr<float>(),
               reinterpret_cast<const uint8_t*>(kv.data_ptr()), kv.stride(0), int(kv.size(0)), out.data_ptr<float>(),
               out.stride(0), B, nullptr, 0, kPage};
  if (upk) {
    check_i32(*upk, "upk");
    TORCH_CHECK(upk->is_contiguous() && upk->numel() >= ublk.numel(), "upk [B, ustride]");
    a.upk = upk->data_ptr<int>();
  }
  if (next_n == 4) launch_logits<4>(a, tm_q, tm_kv, tm_kv);
  else if (next_n == 2) launch_logits<2>(a, tm_q, tm_kv, tm_kv);
  else launch_logits<1>(a, tm_q, tm_kv, tm_kv);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

// idx2f DENSE logits (layers 2 / 8 / 14 / 20, in place of DeepGEMM sm90_fp8_paged_mqa_logits, same arithmetic): every
// position [0, ctx[row]) of every row. q [B, next_n, 32, 128] e4m3; kv [num_pages, P, 1, 132] u8 with P = 64 (ratio 1) or
// 32 (ratio 2), stride(0) = the page stride; weights [rows, 32] f32; ctx [rows] i32; block_table [B, >= ceil(max ctx / P)]
// i32 (entries past a row's pages are never used for values that are kept); out [rows, >= max ctx] f32 (positions >= a
// row's ctx are not written). Unlike DeepGEMM's JIT this is a torch extension: works on every device of one process.
void logits_dense(at::Tensor q, at::Tensor kv, at::Tensor weights, at::Tensor ctx, at::Tensor block_table, at::Tensor out) {
  TORCH_CHECK(q.is_cuda() && q.scalar_type() == at::kFloat8_e4m3fn && q.dim() == 4 && q.is_contiguous(), "q: [B, next_n, 32, 128] fp8");
  const int B = int(q.size(0)), next_n = int(q.size(1));
  TORCH_CHECK(q.size(2) == kHeads && q.size(3) == kHeadDim && (next_n == 1 || next_n == 2 || next_n == 4), "q shape");
  if (!B) return;
  const int P = int(kv.size(1));
  TORCH_CHECK(kv.is_cuda() && kv.scalar_type() == at::kByte && kv.dim() == 4 && (P == 64 || P == 32) && kv.size(2) == 1 &&
                  kv.size(3) == kHeadDim + 4 && kv.stride(0) % 16 == 0 && kv.stride(0) >= P * (kHeadDim + 4) &&
                  reinterpret_cast<uintptr_t>(kv.data_ptr()) % 16 == 0, "kv: fused fp8 index-K pages [n, 64 or 32, 1, 132]");
  TORCH_CHECK(weights.is_cuda() && weights.scalar_type() == at::kFloat && weights.dim() == 2 && weights.size(1) == kHeads &&
                  weights.stride(1) == 1 && weights.stride(0) == kHeads && weights.size(0) >= long(B) * next_n &&
                  reinterpret_cast<uintptr_t>(weights.data_ptr()) % 16 == 0, "weights: [rows, 32] fp32 contiguous rows");
  check_i32(ctx, "ctx");
  check_i32(block_table, "block_table");
  TORCH_CHECK(ctx.is_contiguous() && ctx.numel() >= long(B) * next_n && block_table.dim() == 2 && block_table.stride(1) == 1 &&
                  block_table.size(0) >= B, "logits_dense: metadata");
  TORCH_CHECK(out.is_cuda() && out.scalar_type() == at::kFloat && out.dim() == 2 && out.stride(1) == 1 && out.size(0) >= long(B) * next_n &&
                  out.stride(0) % 4 == 0, "out: [rows, width] fp32");
  TORCH_CHECK(B <= kMaxB, "logits_dense: at most ", kMaxB, " requests per call");
  const c10::cuda::CUDAGuard guard(q.device());
  const cuuint64_t qd[2] = {cuuint64_t(kHeadDim), cuuint64_t(B) * next_n * kHeads};
  const cuuint64_t qs[1] = {cuuint64_t(kHeadDim)};
  const cuuint32_t qb[2] = {cuuint32_t(kHeadDim), cuuint32_t(next_n * kHeads)};
  const CUtensorMap tm_q = encode(q.data_ptr(), 2, qd, qs, qb, CU_TENSOR_MAP_SWIZZLE_128B, "q");
  const cuuint64_t kd[3] = {cuuint64_t(kHeadDim), cuuint64_t(P), cuuint64_t(kv.size(0))};
  const cuuint64_t kst[2] = {cuuint64_t(kHeadDim), cuuint64_t(kv.stride(0))};
  const cuuint32_t kb8[3] = {cuuint32_t(kHeadDim), cuuint32_t(kBlock), 1};
  const cuuint32_t kbp[3] = {cuuint32_t(kHeadDim), cuuint32_t(P), 1};
  const CUtensorMap tm_kv = encode(kv.data_ptr(), 3, kd, kst, kb8, CU_TENSOR_MAP_SWIZZLE_128B, "kv");
  const CUtensorMap tm_kvp = encode(kv.data_ptr(), 3, kd, kst, kbp, CU_TENSOR_MAP_SWIZZLE_128B, "kv page");
  LogitsArgs a{nullptr, nullptr, nullptr, 0, ctx.data_ptr<int>(), block_table.data_ptr<int>(), block_table.stride(0),
               weights.data_ptr<float>(), reinterpret_cast<const uint8_t*>(kv.data_ptr()), kv.stride(0), int(kv.size(0)),
               out.data_ptr<float>(), out.stride(0), B, nullptr, 1, P};
  if (next_n == 4) launch_logits<4>(a, tm_q, tm_kv, tm_kvp);
  else if (next_n == 2) launch_logits<2>(a, tm_q, tm_kv, tm_kvp);
  else launch_logits<1>(a, tm_q, tm_kv, tm_kvp);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

// idx [rows, k] int32 (stride(1) == 1), in place; cblk [rows, >= ceil(max index / 8)] int32 from prep.
void remap(at::Tensor idx, at::Tensor cblk) {
  check_i32(idx, "remap idx");
  check_i32(cblk, "remap cblk");
  TORCH_CHECK(idx.dim() == 2 && idx.stride(1) == 1 && cblk.dim() == 2 && cblk.stride(1) == 1 && cblk.size(0) >= idx.size(0), "remap: layout");
  if (!idx.size(0) || !idx.size(1)) return;
  const c10::cuda::CUDAGuard guard(idx.device());
  cand_remap_kernel<<<int(idx.size(0)), 128, 0, at::cuda::getCurrentCUDAStream()>>>(idx.data_ptr<int>(), idx.stride(0), int(idx.size(1)),
                                                                                     cblk.data_ptr<int>(), cblk.stride(0));
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

int64_t max_cand() { return kMaxCand; }
int64_t block_size() { return kBlock; }
int64_t page_size() { return kPage; }

}  // namespace idx2f_dlc

// indexer2f: block-max + exact top-K for the indexer rows of OWNED sequences (v2).
//
// block_max(logits, lens, out): out[r, b] = the element of logits[r, 8b .. min(8b + 8, lens[r])) with the largest key
//   (key = the order-preserving u32 of the fp32 bits, every NaN highest, +0 > -0): the block key-max of stock
//   select_candidate_blocks / ds41h select_blocks. One read of the logits; a persistent grid walks a device-side prefix of
//   the rows' 8,192-position chunks (no empty CTAs, graph-safe for any row lengths).
//
// select_blocks(bmax, nb_lens, K, out): layer 20's candidate blocks = stock select_candidate_blocks' set: the newest block
//   (nb - 1) pinned to +inf, the top-min(K, nb) block keys (lowest block id on ties), -inf blocks dropped (-1), written in
//   ascending block order and -1 padded (ds41h select_blocks' order; consumers only use the set).
//
// topk(logits, lens, bmax, K, out[, cblk]): the EXACT top-K of row r over [0, lens[r]) under the canonical order (key
//   desc, lowest position on ties), written in ascending position order (rows with lens <= K: 0 .. n-1, -1 padded: stock's
//   contract). Why it is exact: tau = the 22 high bits of the K-th largest block key is <= that key, and the K largest
//   blocks each hold an element with key >= tau, so the K-th largest element key >= tau: every element of the top-K has
//   key >= tau and lies in a block whose key >= tau. The kernel collects exactly those elements (in position order,
//   typically 0.6-4 K) and runs a 3-pass radix select (11 / 11 / 10 bits) on them in shared memory; rows with more than
//   kCMax such elements (massive ties) take the same select streamed over the whole row (counted in `slow`).
//   cblk (compact candidate rows of the consumer layers): output index t -> position 8 * cblk[r, t >> 3] + (t & 7).
// v2: warp-aggregated shared-memory histograms (__match_any_sync): a row's keys share their sign / exponent bits, so the
//   first digit falls into a handful of bins and plain atomics serialized 32-way (v1: 35-61 us per layer, here the goal is
//   the read of the block maxima).
// Deterministic, no allocation, no host sync (CUDA-graph safe).
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <torch/extension.h>

#include <cub/block/block_scan.cuh>

namespace idx2f_dlt {

constexpr int kTPB = 1024;
constexpr int kHB = 2048;
constexpr int kCMax = 8192;
constexpr int kBlock = 8;
constexpr int kChunkBlocks = 1024;  // block_max work item: 1,024 blocks = 8,192 positions
constexpr int kBMThreads = 256;     // 4 blocks per thread
constexpr int kMaxRows = 1024;
constexpr uint32_t kNegInfKey = 0x007fffffu;  // ukey(-inf)
constexpr uint32_t kPosInfKey = 0xff800000u;  // ukey(+inf)

__device__ __forceinline__ uint32_t ukey(float f) {
  const uint32_t b = __float_as_uint(f);
  if ((b & 0x7fffffffu) > 0x7f800000u) return 0xffffffffu;  // NaN: highest (torch radix twiddle maps all NaN up)
  return (b & 0x80000000u) ? ~b : (b | 0x80000000u);
}

// ------------------------------------------------------------------------------------------------ block max
__global__ void __launch_bounds__(kBMThreads) block_max_kernel(const float* __restrict__ lg, long ld,
                                                               const int* __restrict__ lens, int rows,
                                                               float* __restrict__ out, long ldo) {
  using BScan = cub::BlockScan<int, kBMThreads>;
  __shared__ typename BScan::TempStorage scan_tmp;
  __shared__ int s_off[kMaxRows + 1];
  // device-side prefix of the rows' chunk counts (rows <= 1024 = 4 per thread)
  constexpr int kPer = kMaxRows / kBMThreads;
  int cnt[kPer], s = 0;
#pragma unroll
  for (int k = 0; k < kPer; ++k) {
    const int r = int(threadIdx.x) * kPer + k;
    const int nb = r < rows ? (__ldg(lens + r) + kBlock - 1) / kBlock : 0;
    cnt[k] = (nb + kChunkBlocks - 1) / kChunkBlocks;
    s += cnt[k];
  }
  int run, total;
  BScan(scan_tmp).ExclusiveSum(s, run, total);
#pragma unroll
  for (int k = 0; k < kPer; ++k) {
    const int r = int(threadIdx.x) * kPer + k;
    if (r < rows) s_off[r] = run;
    run += cnt[k];
  }
  if (threadIdx.x == 0) s_off[rows] = total;
  __syncthreads();
  for (int item = blockIdx.x; item < total; item += gridDim.x) {
    int lo = 0, hi = rows - 1;  // the row r with s_off[r] <= item < s_off[r + 1]
    while (lo < hi) {
      const int mid = (lo + hi + 1) >> 1;
      if (s_off[mid] <= item) lo = mid; else hi = mid - 1;
    }
    const int r = lo;
    const int n = __ldg(lens + r);
    const int nb = (n + kBlock - 1) / kBlock;
    const int c = item - s_off[r];
#pragma unroll
    for (int k = 0; k < kChunkBlocks / kBMThreads; ++k) {
      const int b = c * kChunkBlocks + k * kBMThreads + int(threadIdx.x);
      if (b >= nb) break;
      const float4* p = reinterpret_cast<const float4*>(lg + r * ld + long(kBlock) * b);
      const float4 x0 = __ldg(p), x1 = __ldg(p + 1);
      const float v[8] = {x0.x, x0.y, x0.z, x0.w, x1.x, x1.y, x1.z, x1.w};
      const int m = min(kBlock, n - kBlock * b);
      uint32_t best = ukey(v[0]);
      float bv = v[0];
#pragma unroll
      for (int j = 1; j < kBlock; ++j) {
        const uint32_t u = ukey(v[j]);
        if (j < m && u > best) best = u, bv = v[j];
      }
      out[r * ldo + b] = bv;
    }
  }
}

// ------------------------------------------------------------------------------------------------ select core
// v3: per-warp private 8-bit histograms. A row's keys share their sign / exponent bits, so every warp hits the same few
// bins: one shared histogram serialized the atomics ACROSS warps (v1 / v2: 10 to 17 us per pass on the longest rows).
using Scan = cub::BlockScan<int, kTPB>;
constexpr int kWarps = kTPB / 32;
constexpr int kBins = 256;
constexpr int kMaxBlocks = 32768;  // rows up to 262,144 positions (block keys staged in shared memory)

struct Smem {
  uint32_t a[kMaxBlocks];       // block keys; then (after the block threshold) the candidates: key [0, kCMax), pos [kCMax, 2 kCMax)
  int sblk[kCMax];              // the selected blocks, ascending
  int whist[kWarps * kBins];    // per-warp histograms
  int hist[kBins];
  typename Scan::TempStorage scan;
  int misc[4];
};
static_assert(2 * kCMax <= kMaxBlocks, "candidate arrays alias the block keys");

// one radix pass: counts of digit (u >> sh) & 255 over the items whose bits above sh match (prefix, pmask); then
// sm.misc[0] = the digit where the suffix count crosses need, sm.misc[1] = #items in higher digits
template <typename Get>
__device__ __forceinline__ void radix_pass(Smem& sm, int N, Get get, uint32_t prefix, uint32_t pmask, int sh, int need) {
  const int tid = threadIdx.x, w = tid >> 5;
  for (int i = tid; i < kWarps * kBins; i += kTPB) sm.whist[i] = 0;
  __syncthreads();
  int* wh = sm.whist + w * kBins;
  for (int i = tid; i < N; i += kTPB) {
    const uint32_t u = get(i);
    if ((u & pmask) == prefix) atomicAdd(&wh[(u >> sh) & 255u], 1);
  }
  __syncthreads();
  if (tid < kBins) {
    int c = 0;
#pragma unroll 8
    for (int k = 0; k < kWarps; ++k) c += sm.whist[k * kBins + tid];
    sm.hist[tid] = c;
  }
  __syncthreads();
  // suffix scan over the 256 bins (descending): thread t < 128 owns bins 255 - 2t, 254 - 2t
  int c0 = 0, c1 = 0, hb = 0;
  if (tid < kBins / 2) hb = kBins - 1 - 2 * tid, c0 = sm.hist[hb], c1 = sm.hist[hb - 1];
  int incl, tot;
  Scan(sm.scan).InclusiveSum(c0 + c1, incl, tot);
  const int excl = incl - c0 - c1;
  if (tid < kBins / 2 && excl < need && need <= incl) {
    if (excl + c0 >= need) sm.misc[0] = hb, sm.misc[1] = excl;
    else sm.misc[0] = hb - 1, sm.misc[1] = excl + c0;
  }
  __syncthreads();
}

// Exact K-th largest key over N items (get(i) -> key); returns kth and #(key > kth) in gt. Requires 1 <= K <= N.
template <typename Get>
__device__ uint32_t kth_key(Smem& sm, int N, int K, Get get, int& gt, int npass = 4) {
  uint32_t prefix = 0, pmask = 0;
  int need = K, above_total = 0;
  for (int pass = 0; pass < npass; ++pass) {
    const int sh = 24 - 8 * pass;
    radix_pass(sm, N, get, prefix, pmask, sh, need);
    const int d = sm.misc[0], above = sm.misc[1];
    __syncthreads();
    prefix |= uint32_t(d) << sh;
    pmask |= 255u << sh;
    need -= above;
    above_total += above;
  }
  gt = above_total;
  return prefix;
}

// Output in position order: item i selected iff key > kth or (key == kth and among the first need_eq ties).
template <typename Get, typename Emit>
__device__ void emit_sel(Smem& sm, int N, uint32_t kth, int need_eq, Get get, Emit val, int* out) {
  const int chunk = (N + kTPB - 1) / kTPB;
  const int i0 = min(N, int(threadIdx.x) * chunk), i1 = min(N, i0 + chunk);
  int g = 0, e = 0;
  for (int i = i0; i < i1; ++i) {
    const uint32_t u = get(i);
    g += u > kth;
    e += u == kth;
  }
  int gb, eb, tot;
  Scan(sm.scan).ExclusiveSum(g, gb, tot);
  __syncthreads();
  Scan(sm.scan).ExclusiveSum(e, eb, tot);
  for (int i = i0; i < i1; ++i) {
    const uint32_t u = get(i);
    if (u > kth) {
      out[gb + min(eb, need_eq)] = val(i);
      ++gb;
    } else if (u == kth) {
      if (eb < need_eq) out[gb + eb] = val(i);
      ++eb;
    }
  }
}

// ------------------------------------------------------------------------------------------------ top-K of a row
struct Args {
  const float* lg;
  long ld;
  const int* lens;
  const float* bmax;
  long ldb;
  int* out;
  long ldo;
  const int* cblk;  // nullptr: positions are the row indices
  long ldc;
  int K;
  int* slow;
  int stop;  // debug: return after stage `stop` (0 = run all)
};

__global__ void __launch_bounds__(kTPB, 1) topk_kernel(const Args a) {
  extern __shared__ __align__(16) uint8_t smem_raw[];
  Smem& sm = *reinterpret_cast<Smem*>(smem_raw);
  const int row = blockIdx.x, tid = threadIdx.x;
  const int n = __ldg(a.lens + row);
  const int K = a.K;
  int* out = a.out + row * a.ldo;
  const int* cblk = a.cblk ? a.cblk + row * a.ldc : nullptr;
  auto posmap = [&](int p) { return cblk ? ((__ldg(cblk + (p >> 3)) << 3) | (p & 7)) : p; };
  if (n <= K) {  // stock contract: 0 .. n-1 then -1
    for (int i = tid; i < K; i += kTPB) out[i] = i < n ? posmap(i) : -1;
    return;
  }
  const float* lrow = a.lg + row * a.ld;
  const float* brow = a.bmax + row * a.ldb;
  const int nb = (n + kBlock - 1) / kBlock;

  // ---- block keys -> shared memory (coalesced)
  for (int i = tid; i < nb; i += kTPB) sm.a[i] = ukey(__ldg(brow + i));
  __syncthreads();
  if (a.stop == 1) return;
  // ---- block threshold tau: the 24 high bits of the K-th largest block key (0 = every block when nb <= K)
  uint32_t tau = 0;
  if (nb > K) {
    int gt_unused;
    tau = kth_key(sm, nb, K, [&](int i) { return sm.a[i]; }, gt_unused, 3);
  }
  if (a.stop == 2) return;
  // ---- the selected blocks (key >= tau), ascending: thread-contiguous chunks of the smem keys + one scan
  bool overflow = false;
  {
    const int chunk = (nb + kTPB - 1) / kTPB;
    const int b0 = min(nb, tid * chunk), b1 = min(nb, b0 + chunk);
    int cnt = 0;
    for (int b = b0; b < b1; ++b) cnt += sm.a[b] >= tau;
    int off, S;
    Scan(sm.scan).ExclusiveSum(cnt, off, S);
    __syncthreads();
    if (S > kCMax) {
      overflow = true;
    } else {
      for (int b = b0; b < b1; ++b)
        if (sm.a[b] >= tau) sm.sblk[off++] = b;
    }
    __syncthreads();
    if (!overflow) sm.misc[2] = S;
    __syncthreads();
  }
  // ---- candidates: the elements >= tau of the selected blocks, in position order (lane-parallel loads, one scan per
  // round of 1,024 blocks); they overwrite the block keys (no longer needed)
  int C = 0;
  uint32_t* ckey = sm.a;
  int* cpos = reinterpret_cast<int*>(sm.a + kCMax);
  if (!overflow) {
    const int S = sm.misc[2];
    for (int r0 = 0; r0 < S; r0 += kTPB) {
      const int i = r0 + tid;
      uint32_t u[8];
      int b = 0, m = 0, c = 0;
      if (i < S) {
        b = sm.sblk[i];
        m = min(kBlock, n - kBlock * b);
        const float4* p = reinterpret_cast<const float4*>(lrow + long(kBlock) * b);
        const float4 x0 = __ldg(p), x1 = __ldg(p + 1);
        const float v[8] = {x0.x, x0.y, x0.z, x0.w, x1.x, x1.y, x1.z, x1.w};
#pragma unroll
        for (int j = 0; j < 8; ++j) {
          u[j] = ukey(v[j]);
          c += (j < m) && u[j] >= tau;
        }
      }
      int off, tot;
      Scan(sm.scan).ExclusiveSum(c, off, tot);
      if (C + tot > kCMax) {
        overflow = true;  // uniform: tot is the CTA-wide sum
        break;
      }
      if (i < S) {
#pragma unroll
        for (int j = 0; j < 8; ++j)
          if ((j < m) && u[j] >= tau) ckey[C + off] = u[j], cpos[C + off] = kBlock * b + j, ++off;
      }
      C += tot;
      __syncthreads();
    }
  }
  __syncthreads();
  if (a.stop == 3) return;
  if (!overflow) {
    auto get = [&](int i) { return ckey[i]; };
    int gt;
    const uint32_t kth = kth_key(sm, C, K, get, gt);
    if (a.stop == 4) return;
    emit_sel(sm, C, kth, K - gt, get, [&](int i) { return posmap(cpos[i]); }, out);
  } else {
    // massive ties (or a degenerate row): the same select streamed over the whole row
    if (tid == 0) atomicAdd(a.slow, 1);
    auto get = [&](int i) { return ukey(__ldg(lrow + i)); };
    int gt;
    const uint32_t kth = kth_key(sm, n, K, get, gt);
    emit_sel(sm, n, kth, K - gt, get, [&](int i) { return posmap(i); }, out);
  }
}

// ------------------------------------------------------------------------------------------------ L20 block select
struct SelArgs {
  const float* bmax;
  long ldb;
  const int* nb_lens;
  int* out;
  long ldo;
  int K;
};

__global__ void __launch_bounds__(kTPB, 1) select_kernel(const SelArgs a) {
  extern __shared__ __align__(16) uint8_t smem_raw[];
  Smem& sm = *reinterpret_cast<Smem*>(smem_raw);
  const int row = blockIdx.x, tid = threadIdx.x;
  const int nb = __ldg(a.nb_lens + row);
  const int K = a.K;
  int* out = a.out + row * a.ldo;
  const float* brow = a.bmax + row * a.ldb;
  if (nb <= 0) {
    for (int i = tid; i < K; i += kTPB) out[i] = -1;
    return;
  }
  // block keys in shared memory, the newest block pinned to +inf (stock: scores[(end - 1) // 8] = inf)
  for (int i = tid; i < nb; i += kTPB) {
    const uint32_t u = ukey(__ldg(brow + i));
    sm.a[i] = i == nb - 1 ? max(u, kPosInfKey) : u;
  }
  __syncthreads();
  auto key = [&](int i) { return sm.a[i]; };
  uint32_t kth = 0;
  int gt = 0;
  if (nb > K) kth = kth_key(sm, nb, K, key, gt);
  // selected blocks in ascending order: -inf blocks (key == ukey(-inf)) are dropped (stock writes -1 for them)
  const bool cut = nb > K;
  const int need_eq = cut ? K - gt : nb;
  const int chunk = (nb + kTPB - 1) / kTPB;
  const int i0 = min(nb, tid * chunk), i1 = min(nb, i0 + chunk);
  int g = 0, e = 0;
  for (int i = i0; i < i1; ++i) {
    const uint32_t u = key(i);
    if (u == kNegInfKey) continue;
    g += cut ? u > kth : 1;
    e += cut && u == kth;
  }
  int gb, eb, tot_g, tot_e;
  Scan(sm.scan).ExclusiveSum(g, gb, tot_g);
  __syncthreads();
  Scan(sm.scan).ExclusiveSum(e, eb, tot_e);
  for (int i = i0; i < i1; ++i) {
    const uint32_t u = key(i);
    if (u == kNegInfKey) continue;
    if (cut ? u > kth : true) {
      out[gb + min(eb, need_eq)] = i;
      ++gb;
    } else if (u == kth) {
      if (eb < need_eq) out[gb + eb] = i;
      ++eb;
    }
  }
  const int written = tot_g + min(tot_e, need_eq);
  for (int i = written + tid; i < K; i += kTPB) out[i] = -1;
}


// ------------------------------------------------------------------------------------------------ prep2 (consumers)
// The union / per-row compaction of layer 20's candidates for the consumer layers, from ASCENDING candidate lists
// (select_blocks above and ds41h select_blocks both write ascending block ids, -1 padded): no atomics. Output = the
// candidate prep's contract (idx2f_cand.cu): ublk [B, 4K] ascending union, uslot [B, 4K, 4] the block's rank in row r's list or -1,
// nunion [B], clen [rows] = #positions of the row's blocks inside [0, n); the row's ascending list cblk IS its candidate
// row (rank = index), so no cblk is written.
constexpr int kPrepT = 1024;
constexpr int kPrepNN = 4;
constexpr int kPrepK = 2048;
constexpr int kPrepWords = 1024;  // rows up to 32,768 blocks

struct PrepSmem {
  int list[kPrepNN][kPrepK];
  unsigned rw[kPrepNN][kPrepWords];
  int rlo[kPrepNN][kPrepWords];
  int cnt[kPrepNN];
  typename cub::BlockScan<int, kPrepT>::TempStorage scan;
};

__device__ __forceinline__ int lower_bound(const int* a, int n, int x) {
  int lo = 0, hi = n;
  while (lo < hi) {
    const int mid = (lo + hi) >> 1;
    if (a[mid] < x) lo = mid + 1; else hi = mid;
  }
  return lo;
}

__global__ void __launch_bounds__(kPrepT, 1) prep2_kernel(const int* __restrict__ cand, long cs, const int* __restrict__ lens,
                                                         int* __restrict__ ublk, int* __restrict__ uslot,
                                                         int* __restrict__ nunion, int* __restrict__ clen,
                                                         const int* __restrict__ bt, long bts, int* __restrict__ upk) {
  extern __shared__ __align__(16) uint8_t smem_raw[];
  PrepSmem& sm = *reinterpret_cast<PrepSmem*>(smem_raw);
  const int b = blockIdx.x, tid = threadIdx.x;
  const int ustride = kPrepNN * kPrepK;
  for (int i = tid; i < kPrepNN * kPrepK; i += kPrepT) {
    const int r = i / kPrepK, j = i - r * kPrepK;
    sm.list[r][j] = __ldg(cand + long(b * kPrepNN + r) * cs + j);
  }
  __syncthreads();
  if (tid < kPrepNN) {  // valid prefix length: the first -1 (ascending ids, then -1 padding)
    int lo = 0, hi = kPrepK;
    while (lo < hi) {
      const int mid = (lo + hi) >> 1;
      if (sm.list[tid][mid] >= 0) lo = mid + 1; else hi = mid;
    }
    sm.cnt[tid] = lo;
  }
  __syncthreads();
  int nbmax = 0;
#pragma unroll
  for (int r = 0; r < kPrepNN; ++r) nbmax = max(nbmax, (__ldg(lens + b * kPrepNN + r) + kBlock - 1) / kBlock);
  const int nw = min(kPrepWords, (nbmax + 31) / 32);
  for (int t = tid; t < kPrepNN * nw; t += kPrepT) {
    const int r = t / nw, w = t - r * nw;
    const int lo = lower_bound(sm.list[r], sm.cnt[r], 32 * w), hi = lower_bound(sm.list[r], sm.cnt[r], 32 * w + 32);
    unsigned bits = 0;
    for (int k = lo; k < hi; ++k) bits |= 1u << (sm.list[r][k] & 31);
    sm.rw[r][w] = bits;
    sm.rlo[r][w] = lo;
  }
  __syncthreads();
  unsigned u = 0;
  if (tid < nw) {
#pragma unroll
    for (int r = 0; r < kPrepNN; ++r) u |= sm.rw[r][tid];
  }
  int pre, total;
  cub::BlockScan<int, kPrepT>(sm.scan).ExclusiveSum(__popc(u), pre, total);
  int* ub = ublk + long(b) * ustride;
  int* us = uslot + long(b) * ustride * kPrepNN;
  while (u) {
    const int bit = __ffs(u) - 1;
    u &= u - 1;
    const int ui = pre++;
    const int blk = 32 * tid + bit;
    ub[ui] = blk;
    if (upk != nullptr) upk[long(b) * ustride + ui] = (__ldg(bt + long(b) * bts + (blk >> 3)) << 3) | (blk & 7);
#pragma unroll
    for (int r = 0; r < kPrepNN; ++r) {
      const unsigned m = sm.rw[r][tid];
      us[long(ui) * kPrepNN + r] = ((m >> bit) & 1u) ? sm.rlo[r][tid] + __popc(m & ((1u << bit) - 1u)) : -1;
    }
  }
  if (tid == 0) nunion[b] = total;
  if (tid < kPrepNN) {
    const int n = __ldg(lens + b * kPrepNN + tid);
    const int nb = (n + kBlock - 1) / kBlock;
    const int c = sm.cnt[tid];
    const bool has = c > 0 && sm.list[tid][c - 1] == nb - 1;  // only the newest block can be partial
    clen[b * kPrepNN + tid] = c * kBlock - (has ? kBlock - (n - kBlock * (nb - 1)) : 0);
  }
}

// ------------------------------------------------------------------------------------------------ host
void check_rows(const at::Tensor& t, const char* name, at::ScalarType st) {
  TORCH_CHECK(t.is_cuda() && t.scalar_type() == st && t.dim() == 2 && t.stride(1) == 1, name, ": 2-D CUDA, stride(1) 1");
}

template <typename F>
void set_smem_once(F* fn, int dev) {
  static bool set[64] = {};
  if (!set[dev]) {
    TORCH_CHECK(cudaFuncSetAttribute(fn, cudaFuncAttributeMaxDynamicSharedMemorySize, int(sizeof(Smem))) == cudaSuccess,
                "smem attribute");
    set[dev] = true;
  }
}

void block_max(at::Tensor logits, at::Tensor lens, at::Tensor out, int64_t max_len) {
  check_rows(logits, "logits", at::kFloat);
  check_rows(out, "out", at::kFloat);
  TORCH_CHECK(lens.is_cuda() && lens.scalar_type() == at::kInt && lens.is_contiguous() && lens.numel() >= logits.size(0), "lens");
  TORCH_CHECK(logits.stride(0) % 4 == 0 && reinterpret_cast<uintptr_t>(logits.data_ptr()) % 16 == 0, "logits rows 16-B aligned");
  const int rows = int(logits.size(0));
  TORCH_CHECK(rows <= kMaxRows, "rows <= 1024");
  const int nb = int((max_len + kBlock - 1) / kBlock);
  TORCH_CHECK(out.size(1) >= nb && out.size(0) >= rows, "out [rows, >= ceil(max_len / 8)]");
  TORCH_CHECK(logits.size(1) >= nb * kBlock, "logits width >= 8 * ceil(max_len / 8)");
  if (!rows || !nb) return;
  const c10::cuda::CUDAGuard guard(logits.device());
  const int sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
  block_max_kernel<<<2 * sms, kBMThreads, 0, at::cuda::getCurrentCUDAStream()>>>(
      logits.data_ptr<float>(), logits.stride(0), lens.data_ptr<int>(), rows, out.data_ptr<float>(), out.stride(0));
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

void topk(at::Tensor logits, at::Tensor lens, at::Tensor bmax, int64_t k, at::Tensor out, std::optional<at::Tensor> cblk,
          at::Tensor slow, int64_t stop) {
  check_rows(logits, "logits", at::kFloat);
  check_rows(bmax, "bmax", at::kFloat);
  check_rows(out, "out", at::kInt);
  TORCH_CHECK(lens.is_cuda() && lens.scalar_type() == at::kInt && lens.is_contiguous(), "lens");
  TORCH_CHECK(slow.is_cuda() && slow.scalar_type() == at::kInt && slow.numel() >= 1, "slow counter");
  const int rows = int(logits.size(0));
  TORCH_CHECK(lens.numel() >= rows && bmax.size(0) >= rows && out.size(0) >= rows && out.size(1) >= k && k > 0 && k <= kCMax, "shapes");
  TORCH_CHECK(bmax.size(1) <= kMaxBlocks, "rows up to 262,144 positions");
  TORCH_CHECK(k <= kCMax, "k <= 8192");
  if (cblk) check_rows(*cblk, "cblk", at::kInt);
  if (!rows) return;
  const c10::cuda::CUDAGuard guard(logits.device());
  set_smem_once(topk_kernel, logits.get_device());
  Args a{logits.data_ptr<float>(), logits.stride(0), lens.data_ptr<int>(), bmax.data_ptr<float>(), bmax.stride(0),
         out.data_ptr<int>(), out.stride(0), cblk ? cblk->data_ptr<int>() : nullptr, cblk ? cblk->stride(0) : 0, int(k),
         slow.data_ptr<int>(), int(stop)};
  topk_kernel<<<rows, kTPB, sizeof(Smem), at::cuda::getCurrentCUDAStream()>>>(a);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

void select_blocks(at::Tensor bmax, at::Tensor nb_lens, int64_t k, at::Tensor out) {
  check_rows(bmax, "bmax", at::kFloat);
  check_rows(out, "out", at::kInt);
  TORCH_CHECK(nb_lens.is_cuda() && nb_lens.scalar_type() == at::kInt && nb_lens.is_contiguous(), "nb_lens");
  const int rows = int(out.size(0));
  TORCH_CHECK(nb_lens.numel() >= rows && bmax.size(0) >= rows && out.size(1) >= k && k > 0, "shapes");
  TORCH_CHECK(bmax.size(1) <= kMaxBlocks, "at most 32,768 blocks per row");
  if (!rows) return;
  const c10::cuda::CUDAGuard guard(bmax.device());
  set_smem_once(select_kernel, bmax.get_device());
  SelArgs a{bmax.data_ptr<float>(), bmax.stride(0), nb_lens.data_ptr<int>(), out.data_ptr<int>(), out.stride(0), int(k)};
  select_kernel<<<rows, kTPB, sizeof(Smem), at::cuda::getCurrentCUDAStream()>>>(a);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

void prep2(at::Tensor cand, at::Tensor lens, at::Tensor ublk, at::Tensor uslot, at::Tensor nunion, at::Tensor clen,
           std::optional<at::Tensor> block_table, std::optional<at::Tensor> upk) {
  check_rows(cand, "cand", at::kInt);
  TORCH_CHECK(cand.size(1) == kPrepK, "cand [rows, 2048]");
  TORCH_CHECK(lens.is_cuda() && lens.scalar_type() == at::kInt && lens.is_contiguous(), "lens");
  const int rows = int(lens.numel());
  TORCH_CHECK(rows % kPrepNN == 0 && cand.size(0) >= rows, "rows = 4 x requests");
  const int B = rows / kPrepNN;
  for (auto* t : {&ublk, &uslot, &nunion, &clen})
    TORCH_CHECK(t->is_cuda() && t->scalar_type() == at::kInt && t->is_contiguous(), "prep2 outputs int32 contiguous");
  TORCH_CHECK(ublk.numel() >= long(B) * kPrepNN * kPrepK && uslot.numel() >= long(B) * kPrepNN * kPrepK * kPrepNN &&
                  nunion.numel() >= B && clen.numel() >= rows, "prep2 output sizes");
  if (!B) return;
  const c10::cuda::CUDAGuard guard(cand.device());
  static bool set[64] = {};
  const int dev = cand.get_device();
  if (!set[dev]) {
    TORCH_CHECK(cudaFuncSetAttribute(prep2_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, int(sizeof(PrepSmem))) == cudaSuccess,
                "prep2 smem");
    set[dev] = true;
  }
  TORCH_CHECK(block_table.has_value() == upk.has_value(), "block_table and upk together");
  if (upk) {
    check_rows(*block_table, "block_table", at::kInt);
    TORCH_CHECK(upk->is_cuda() && upk->scalar_type() == at::kInt && upk->is_contiguous() && upk->numel() >= ublk.numel(), "upk");
  }
  prep2_kernel<<<B, kPrepT, sizeof(PrepSmem), at::cuda::getCurrentCUDAStream()>>>(
      cand.data_ptr<int>(), cand.stride(0), lens.data_ptr<int>(), ublk.data_ptr<int>(), uslot.data_ptr<int>(),
      nunion.data_ptr<int>(), clen.data_ptr<int>(), block_table ? block_table->data_ptr<int>() : nullptr,
      block_table ? block_table->stride(0) : 0, upk ? upk->data_ptr<int>() : nullptr);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

}  // namespace idx2f_dlt


namespace idx2f_dl {

// q [B, 4, 32, 128] e4m3, kv [pages, P, 1, 132], weights [rows, 32] f32, ctx [rows] i32 (the layer's row lengths),
// block_table [B, *] i32; ws_logits / ws_bm flat f32 workspaces (EagerWorkspace.f32 / .bmax); bstep pseudo-requests per
// slice, width = the logits row stride, max_len = the layer's longest row; out [rows, >= K] i32; slow [1] i32;
// layer 20: nb_lens [rows] i32 and cand [rows, >= cand_k] i32. Returns the number of slices.
int64_t dense_layer(at::Tensor q, at::Tensor kv, at::Tensor weights, at::Tensor ctx, at::Tensor block_table,
                    at::Tensor ws_logits, at::Tensor ws_bm, int64_t bstep, int64_t width, int64_t max_len, int64_t K,
                    at::Tensor out, at::Tensor slow, std::optional<at::Tensor> nb_lens, std::optional<at::Tensor> cand,
                    int64_t cand_k) {
  const int64_t B = q.size(0), NN = q.size(1);
  const int64_t nb = std::max<int64_t>((max_len + 7) / 8, 1);
  TORCH_CHECK(bstep > 0 && ctx.is_contiguous() && ws_logits.is_contiguous() && ws_bm.is_contiguous(), "dense_layer args");
  TORCH_CHECK(nb_lens.has_value() == cand.has_value(), "nb_lens and cand together (layer 20)");
  int64_t n = 0;
  for (int64_t b0 = 0; b0 < B; b0 += bstep, ++n) {
    const int64_t b1 = std::min(B, b0 + bstep), r0 = NN * b0, rows = NN * (b1 - b0);
    TORCH_CHECK(rows * width <= ws_logits.numel() && rows * nb <= ws_bm.numel(), "dense_layer: workspace too small");
    at::Tensor lg = ws_logits.narrow(0, 0, rows * width).view({rows, width});
    at::Tensor sl = ctx.narrow(0, r0, rows);
    idx2f_dlc::logits_dense(q.narrow(0, b0, b1 - b0), kv, weights.narrow(0, r0, rows), sl,
                            block_table.narrow(0, b0, b1 - b0), lg);
    at::Tensor bm = ws_bm.narrow(0, 0, rows * nb).view({rows, nb});
    for (int64_t c0 = 0; c0 < rows; c0 += 1024) {   // = idx2f.block_max (MAX_CALL_ROWS)
      const int64_t c1 = std::min(rows, c0 + 1024);
      idx2f_dlt::block_max(lg.narrow(0, c0, c1 - c0), sl.narrow(0, c0, c1 - c0), bm.narrow(0, c0, c1 - c0), max_len);
    }
    if (cand) idx2f_dlt::select_blocks(bm, nb_lens->narrow(0, r0, rows), cand_k, cand->narrow(0, r0, rows));
    idx2f_dlt::topk(lg, sl, bm, K, out.narrow(0, r0, rows), std::nullopt, slow, 0);
  }
  return n;
}

}  // namespace idx2f_dl

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("dense_layer", &idx2f_dl::dense_layer, "one eager dense index layer, its slices issued from C++ (bit-identical)");
}
